class Variable:
    def __init__(self, data):
        self.data = float(data)
        self.grad = 0.0

class Square:
    def __call__(self, x):
        y = Variable(x.data ** 2)
        self.input = x
        return y

    def backward(self, gy):
        return 2 * self.input.data * gy

x = Variable(3.0)
f = Square()
y = f(x)
print(y.data)
print(f.backward(1.0))

